ST.xhtml:
// =============================================================================
// 场景：固件包下发到 PLC 后做完整性自检——本端按已知算法（SHA-256）算
//       固件哈希，与厂商签名内嵌的预期哈希比对，不一致拒绝运行新固件。
// 价值：手写 SHA-256 200+ 行几乎不可能调对；本函数封装 CryptoAPI，单调
//       用得到 32 字节哈希。比 F_CheckSum16 / CRC 强度高一个量级，能抗
//       篡改。
// 验证步骤：
//   1. 登录后 arFirmwareSha256 全 0，bHashSucceeded = FALSE。
//   2. 写 bHashRequest := TRUE 触发一次。
//   3. 观察 bHashSucceeded = TRUE，arFirmwareSha256 各字节填上 32 字节哈希值。
//   4. 验证算法正确：用 PowerShell `Get-FileHash -Algorithm SHA256` 或
//      Python `hashlib.sha256(b'firmware_v2.1.0_release').hexdigest()`
//      算出预期哈希，与 arFirmwareSha256 字节对齐应一致。
//   5. 把 sFirmwareIdentity 末尾加一个空格，重新触发——arFirmwareSha256
//      会完全不同，印证 SHA 的"雪崩效应"。
//   6. 错误演示：把 SIZEOF(arFirmwareSha256) 改成 16（不够 SHA-256 的 32），
//      bHashSucceeded 会变 FALSE——印证 §5 nHash 必须匹配算法。
// =============================================================================

IF bHashRequest THEN
    // 单次调用：SHA-256 需要 32 字节目标 buffer
    bHashSucceeded := F_GenerateHashValue(
        hashMode := E_HashMode.SHA256,
        pData    := ADR(sFirmwareIdentity),
        nData    := LEN(sFirmwareIdentity),
        pHash    := ADR(arFirmwareSha256),
        nHash    := SIZEOF(arFirmwareSha256));
    bHashRequest := FALSE;
END_IF;
